const {fitDataAsync, OPTIMIZERS} = DataScience;
const {vec} = NMath;
const components = 50;
const samples = await IO.loadMNIST();
if (samples.length < 2) throw new Error("At least two MNIST images are required");
const pca = PCA.new(samples, components);
const targets = samples.map(sample => vec(...pca.proj(sample)));
const model = HKmeans.new(targets, {rho: 0.1, kmeansIter: 2}).fit();

const randomImage = () => Float32Array.from({length: 28 * 28}, () => Math.random());

// For a unique nearest point, the gradient of its distance is the normalized displacement.
const gradient = point => {
    const distance = model.udf(point, 1);
    if (distance === 0) return vec.zero(components);
    return point.sub(model.findNN(point)).scale(1 / distance);
};
// Sample the same random-image-to-digit paths as the flow-matching demo.
const training = targets.flatMap(target => Array.from({length: 2}, () => {
    const source = vec(...pca.proj(randomImage()));
    const t = Math.random();
    const point = source.scale(1 - t).add(target.scale(t));
    return {point, gradient: gradient(point)};
}));

// Learn the PCA-space gradient; integration follows its negative.
const field = NeuralNet.builder()
    .input(components)
    .layer(32)
    .layer(32)
    .layer(components, NeuralNet.ACTIVATIONS.linear)
    .build();
const {theta} = await fitDataAsync(
    training.map(sample => sample.point),
    training.map(sample => sample.gradient),
    field.model,
    {
        epochs: 2500,
        batch: 32,
        optimizer: OPTIMIZERS.ADAMW({learningRate: 0.005}),
        continuationEvery: 100,
        continuationFn: ({epoch, loss}) => console.log(`Epoch ${epoch + 1}, loss ${loss.toFixed(4)}`),
    },
);
field.setWeights(theta);

const steps = 100;
let time = 0;
let trajectory;
const image = IO.paintMNIST(new Float32Array(28 * 28));
const showTime = () => {
    if (!trajectory) return;
    const pixels = pca.gen(trajectory[Math.round(time * steps)].components).toArray();
    image.update(Float32Array.from(pixels, value => Math.max(0, Math.min(1, value))));
};
const drawing = IO.drawMNIST({
    randomButton: true,
    onSubmit: data => {
        const initial = vec(...pca.proj(data));
        const flowLength = model.udf(initial, 1);
        trajectory = [initial];
        for (let step = 0; step < steps; step++) {
            const point = trajectory[step];
            const direction = vec(...field.eval(point)).scale(-1);
            trajectory.push(point.add(direction.scale(flowLength / steps)));
        }
        showTime();
    },
});
const ui = IO.UI(
    {type: "canvas", value: () => drawing},
    {type: "canvas", value: () => image},
    {type: "slider", value: () => ({
        title: "t:", min: 0, max: 1, step: 1 / steps, value: 0,
        onChange: value => { time = value; showTime(); },
    })},
);
ui;
